1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Step = {
9	  op: string;
10	  items?: Item[];
11	};
12	
13	export type Customer = {
14	  yearsWithMHPCO: number;
15	};
16	
17	export type Scenario = {
18	  customer: Customer;
19	  steps: Step[];
20	};
21	
22	export type QuoteResult = {
23	  premium: number;
24	};
25	
26	// A scenario's results are heterogeneous: a quote step yields a premium, and a
27	// claim step will yield a payout. The union has one member today.
28	export type StepResult = QuoteResult;
29	
30	export type ScenarioResults = {
31	  results: StepResult[];
32	};
33	
34	const PROCESSING_FEE = 5;
35	
36	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
37	  sword: 100,
38	  amulet: 60,
39	  staff: 80,
40	  potion: 40,
41	  rune: 25,
42	  moonstone: 25,
43	};
44	
45	// Charged on every quote, unconditionally — it is the cost of assessing the
46	// items, not a penalty for being a new customer. Named "first insurance" in
47	// some of the domain material, which misleads: it does not depend on customer
48	// history or on the quote's position in the scenario.
49	const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
50	
51	const percentOf = (amount: number, percent: number): number =>
52	  (amount * percent) / 100;
53	
54	const itemBasePremium = (item: Item): number =>
55	  BASE_PREMIUM_BY_TYPE[item.type];
56	
57	const BLOCK_SIZE = 3;
58	
59	const BLOCK_PREMIUM = 60;
60	
61	const sumOf = (amounts: number[]): number =>
62	  amounts.reduce((sum, amount) => sum + amount, 0);
63	
64	const formsABlock = (items: Item[]): boolean => items.length === BLOCK_SIZE;
65	
66	const sumOfItemBasePremiums = (items: Item[]): number =>
67	  sumOf(items.map(itemBasePremium));
68	
69	// Items of the same type are "alike" and are priced together, so the policy
70	// base premium is computed group by group rather than item by item.
71	const alikeGroups = (items: Item[]): Item[][] => {
72	  const groupsByType = new Map<string, Item[]>();
73	
74	  for (const item of items) {
75	    groupsByType.set(item.type, [...(groupsByType.get(item.type) ?? []), item]);
76	  }
77	
78	  return [...groupsByType.values()];
79	};
80	
81	const alikeGroupBasePremium = (alikeItems: Item[]): number =>
82	  formsABlock(alikeItems)
83	    ? BLOCK_PREMIUM
84	    : sumOfItemBasePremiums(alikeItems);
85	
86	const policyBasePremium = (items: Item[]): number =>
87	  sumOf(alikeGroups(items).map(alikeGroupBasePremium));
88	
89	const roundPremiumInMHPCOsFavor = (amount: number): number =>
90	  Math.ceil(amount);
91	
92	// The inputs a single quote is computed from: `items` drives the base premium
93	// and item-scoped surcharges, `customer` and `precedingQuoteCount` drive the
94	// policy-wide modifiers. The count is of preceding QUOTE steps, not of steps in
95	// general — a claim step is not a contract and must not trigger the follow-up
96	// discount.
97	type QuoteRequest = {
98	  customer: Customer;
99	  items: Item[];
100	  precedingQuoteCount: number;
101	};
102	
103	const LOYALTY_YEARS = 2;
104	
105	const LOYALTY_DISCOUNT_PERCENT = 20;
106	
107	// Modifier percents are signed so surcharges and discounts can be summed
108	// uniformly; a discount enters the sum as its negation.
109	const asDiscount = (percent: number): number => -percent;
110	
111	const isLoyal = (customer: Customer): boolean =>
112	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
113	
114	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
115	
116	const isFollowUpContract = (request: QuoteRequest): boolean =>
117	  request.precedingQuoteCount > 0;
118	
119	const policyModifierPercents = (request: QuoteRequest): number[] => [
120	  INITIAL_ASSESSMENT_SURCHARGE_PERCENT,
121	  ...(isLoyal(request.customer) ? [asDiscount(LOYALTY_DISCOUNT_PERCENT)] : []),
122	  ...(isFollowUpContract(request)
123	    ? [asDiscount(FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT)]
124	    : []),
125	];
126	
127	// Policy-wide modifiers do NOT compound: each is an independent percentage of
128	// the policy base premium, and they are summed. Chaining them (base * 1.1 * 0.8)
129	// would give a different, wrong answer.
130	const applyPolicyModifiers = (
131	  basePremium: number,
132	  request: QuoteRequest,
133	): number =>
134	  basePremium +
135	  sumOf(
136	    policyModifierPercents(request).map((percent) =>
137	      percentOf(basePremium, percent),
138	    ),
139	  );
140	
141	const CURSE_SURCHARGE_PERCENT = 50;
142	
143	const HIGH_ENCHANTMENT_LEVEL = 5;
144	
145	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
146	
147	const isHighlyEnchanted = (item: Item): boolean =>
148	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
149	
150	const isCursed = (item: Item): boolean => item.cursed === true;
151	
152	type ItemSurchargeRule = {
153	  applies: (item: Item) => boolean;
154	  percent: number;
155	};
156	
157	const ITEM_SURCHARGE_RULES: ItemSurchargeRule[] = [
158	  { applies: isCursed, percent: CURSE_SURCHARGE_PERCENT },
159	  { applies: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
160	];
161	
162	// Item-scoped surcharges are charged on the item's own base premium, so they
163	// must NOT go through applyPolicyModifiers.
164	const itemSurcharges = (item: Item): number =>
165	  sumOf(
166	    ITEM_SURCHARGE_RULES.filter((rule) => rule.applies(item)).map((rule) =>
167	      percentOf(itemBasePremium(item), rule.percent),
168	    ),
169	  );
170	
171	const policyItemSurcharges = (items: Item[]): number =>
172	  sumOf(items.map(itemSurcharges));
173	
174	const quotePremium = (request: QuoteRequest): number =>
175	  roundPremiumInMHPCOsFavor(
176	    applyPolicyModifiers(policyBasePremium(request.items), request) +
177	      policyItemSurcharges(request.items) +
178	      PROCESSING_FEE,
179	  );
180	
181	const isQuote = (step: Step): boolean => step.op === "quote";
182	
183	// What the scenario has accumulated so far. Steps are folded rather than mapped
184	// because a step's result depends on the steps before it: `precedingQuoteCount`
185	// drives the follow-up discount today, and claim steps will thread a remaining
186	// cap through the same carry.
187	type ScenarioState = {
188	  results: StepResult[];
189	  precedingQuoteCount: number;
190	};
191	
192	const INITIAL_STATE: ScenarioState = { results: [], precedingQuoteCount: 0 };
193	
194	// Running a step is a state transition: it reads the carry accumulated by the
195	// preceding steps and returns the next carry. Every step kind gets its own
196	// runner, so `runStep` below is pure dispatch on `op` — the place a claim runner
197	// will be added without touching the quote path.
198	type StepRunner = (
199	  customer: Customer,
200	  state: ScenarioState,
201	  step: Step,
202	) => ScenarioState;
203	
204	const appendResult = (
205	  state: ScenarioState,
206	  result: StepResult,
207	): ScenarioState => ({ ...state, results: [...state.results, result] });
208	
209	const runQuoteStep: StepRunner = (customer, state, step) => {
210	  const premium = quotePremium({
211	    customer,
212	    items: step.items ?? [],
213	    precedingQuoteCount: state.precedingQuoteCount,
214	  });
215	
216	  return {
217	    ...appendResult(state, { premium }),
218	    precedingQuoteCount: state.precedingQuoteCount + 1,
219	  };
220	};
221	
222	const runStep: StepRunner = (customer, state, step) =>
223	  isQuote(step) ? runQuoteStep(customer, state, step) : state;
224	
225	// The customer is scenario-wide, so it is closed over rather than threaded
226	// through the fold alongside the per-step state.
227	const stepRunnerFor =
228	  (customer: Customer) => (state: ScenarioState, step: Step) =>
229	    runStep(customer, state, step);
230	
231	export const runScenario = (scenario: Scenario): ScenarioResults => ({
232	  results: scenario.steps.reduce(stepRunnerFor(scenario.customer), INITIAL_STATE)
233	    .results,
234	});
